import{_ as e,o,c as i,a2 as r}from"./chunks/framework.CgxQ0r6v.js";const p=JSON.parse('{"title":"Manual de Estudio Profundo: Evaluación 3","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_I/documentacion/I-III/Lectura_Catedra_Evaluacion_3.md","filePath":"materias/Proyecto_Sociotecnologico_I/documentacion/I-III/Lectura_Catedra_Evaluacion_3.md"}'),t={name:"materias/Proyecto_Sociotecnologico_I/documentacion/I-III/Lectura_Catedra_Evaluacion_3.md"};function n(l,a,s,c,u,d){return o(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="manual-de-estudio-profundo-evaluacion-3" tabindex="-1">Manual de Estudio Profundo: Evaluación 3 <a class="header-anchor" href="#manual-de-estudio-profundo-evaluacion-3" aria-label="Permalink to &quot;Manual de Estudio Profundo: Evaluación 3&quot;">​</a></h1><h2 id="materia-proyecto-sociotecnologico-trayecto-i" tabindex="-1">Materia: Proyecto Sociotecnológico (Trayecto I) <a class="header-anchor" href="#materia-proyecto-sociotecnologico-trayecto-i" aria-label="Permalink to &quot;Materia: Proyecto Sociotecnológico (Trayecto I)&quot;">​</a></h2><h3 id="eje-tematico-el-informe-final-y-las-normas-de-la-uptt" tabindex="-1">Eje Temático: El Informe Final y las Normas de la UPTT <a class="header-anchor" href="#eje-tematico-el-informe-final-y-las-normas-de-la-uptt" aria-label="Permalink to &quot;Eje Temático: El Informe Final y las Normas de la UPTT&quot;">​</a></h3><hr><h2 id="🧭-introduccion-la-memoria-escrita" tabindex="-1">🧭 Introducción: La Memoria Escrita <a class="header-anchor" href="#🧭-introduccion-la-memoria-escrita" aria-label="Permalink to &quot;🧭 Introducción: La Memoria Escrita&quot;">​</a></h2><p>En la ciencia y la ingeniería, el conocimiento que no se escribe, no existe. Reparaste las computadoras de un liceo con éxito rotundo; los estudiantes están felices y las secretarias trabajan rápido. Sin embargo, si un año después un nuevo ingeniero quiere entender qué sistema operativo instalaste y por qué, no podrá saberlo.</p><p>El <strong>Informe Final</strong> no es un &quot;castigo académico&quot; para que imprimas 50 páginas. Es el documento técnico que certifica ante la universidad y ante el Estado que lograste resolver un problema usando la ciencia informática.</p><hr><h2 id="🏛️-capitulo-i-estructura-normativa-de-la-uptt-reglamento-psi-t" tabindex="-1">🏛️ CAPÍTULO I: Estructura Normativa de la UPTT (Reglamento PSI/T) <a class="header-anchor" href="#🏛️-capitulo-i-estructura-normativa-de-la-uptt-reglamento-psi-t" aria-label="Permalink to &quot;🏛️ CAPÍTULO I: Estructura Normativa de la UPTT (Reglamento PSI/T)&quot;">​</a></h2><p>El informe no se redacta como un ensayo libre. Debe seguir estrictamente el Manual de Normas para la Elaboración de Trabajos de Proyecto de la UPTT. Toda desviación en el margen, interlineado o estructura de capítulos es causal de corrección (y posible aplazamiento).</p><h3 id="_1-1-estructura-clasica-por-capitulos" tabindex="-1">1.1 Estructura Clásica por Capítulos <a class="header-anchor" href="#_1-1-estructura-clasica-por-capitulos" aria-label="Permalink to &quot;1.1 Estructura Clásica por Capítulos&quot;">​</a></h3><p>El informe suele compilar todo lo que ya hiciste a lo largo del año (literalmente, es copiar y pulir lo que hiciste en las evaluaciones pasadas):</p><ul><li><strong>Capítulo I: El Diagnóstico.</strong> Contiene el abordaje, la descripción de la comunidad y el Planteamiento del Problema (El Tronco del Árbol de Problemas).</li><li><strong>Capítulo II: Marco Teórico y Legal.</strong> Los antecedentes (¿quién ha reparado equipos antes?), las bases teóricas (¿qué es GNU/Linux?, ¿qué es mantenimiento preventivo?) y las bases legales (Ley de Infogobierno).</li><li><strong>Capítulo III: Marco Metodológico (El EML).</strong> Aquí plasmas la matriz del marco lógico, los árboles, la EAP y el presupuesto.</li><li><strong>Capítulo IV: Ejecución y Resultados.</strong> Narra detalladamente (con fechas y datos del monitoreo) cómo realizaste el soporte técnico. Se incluyen los indicadores de éxito.</li><li><strong>Conclusiones y Recomendaciones.</strong></li></ul><hr><h2 id="🧩-capitulo-ii-redaccion-cientifica" tabindex="-1">🧩 CAPÍTULO II: Redacción Científica <a class="header-anchor" href="#🧩-capitulo-ii-redaccion-cientifica" aria-label="Permalink to &quot;🧩 CAPÍTULO II: Redacción Científica&quot;">​</a></h2><p>Muchos estudiantes de ingeniería son expertos con un destornillador pero sufren frente a un teclado al redactar.</p><h3 id="_2-1-la-tercera-persona-y-el-lenguaje-impersonal" tabindex="-1">2.1 La Tercera Persona y el Lenguaje Impersonal <a class="header-anchor" href="#_2-1-la-tercera-persona-y-el-lenguaje-impersonal" aria-label="Permalink to &quot;2.1 La Tercera Persona y el Lenguaje Impersonal&quot;">​</a></h3><p>En la redacción científica e investigativa (Normas APA y Normas UPTT) <strong>NUNCA se escribe en primera persona</strong>.</p><ul><li>❌ <strong>Incorrecto:</strong> &quot;Nosotros fuimos a la comunidad el martes y reparamos mi computadora&quot;. (Suena a diario personal).</li><li>✅ <strong>Correcto:</strong> &quot;El equipo investigador se trasladó a la comunidad el día martes para ejecutar el mantenimiento preventivo de las estaciones de trabajo&quot;.</li></ul><h3 id="_2-2-coherencia-y-cohesion" tabindex="-1">2.2 Coherencia y Cohesión <a class="header-anchor" href="#_2-2-coherencia-y-cohesion" aria-label="Permalink to &quot;2.2 Coherencia y Cohesión&quot;">​</a></h3><p>Cada párrafo debe conectar lógicamente con el anterior. Evita el &quot;lenguaje de chat&quot; y los modismos locales. Utiliza siempre el término técnico correcto (es un <em>periférico de entrada</em>, no un <em>aparatito</em>).</p><hr><h2 id="🏗️-capitulo-iii-los-anexos-y-las-evidencias-el-portafolio" tabindex="-1">🏗️ CAPÍTULO III: Los Anexos y las Evidencias (El Portafolio) <a class="header-anchor" href="#🏗️-capitulo-iii-los-anexos-y-las-evidencias-el-portafolio" aria-label="Permalink to &quot;🏗️ CAPÍTULO III: Los Anexos y las Evidencias (El Portafolio)&quot;">​</a></h2><p>El informe escrito narra la historia, pero los <strong>Anexos</strong> son los que demuestran que no es una historia de ficción.</p><p>Todo documento oficial generado en la comunidad va en los anexos:</p><ol><li><strong>La Carta de Aceptación:</strong> Firmada al inicio del Trayecto I.</li><li><strong>Las Bitácoras de Campo:</strong> Con las firmas de cada visita.</li><li><strong>El Acta de Entrega Final:</strong> El documento más importante. Demuestra que la comunidad recibió el soporte técnico a satisfacción.</li><li><strong>Galería Fotográfica:</strong> Imágenes bien iluminadas y tituladas (&quot;Figura 1: Proceso de limpieza de la Tarjeta Madre&quot;).</li></ol><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p><strong>El Papel de la UPSIT (Unidad de Proyecto Socio Integrador)</strong> Tu informe final no se aprueba solo en clase. Debe ser entregado y revisado por el comité técnico de la UPSIT de la universidad. Ellos revisarán con lupa que el impacto socio-tecnológico sea real y que los formatos institucionales se hayan respetado escrupulosamente.</p></div><p>Con el informe impreso y empastado (y aprobado por el tutor), solo queda el último obstáculo: ponerse de pie y defender tu honor informático frente al jurado. Eso lo veremos en la última evaluación: <strong>La Defensa Comunitaria</strong>.</p>',28)])])}const g=e(t,[["render",n]]);export{p as __pageData,g as default};
